    int n = pumps.length;
    for (int s = 0; s < n; s++) {
        long tank = 0;
        boolean ok = true;
        for (int j = 0; j < n; j++) {
            int idx = (s + j) % n;
            tank += (long) pumps[idx][0] - pumps[idx][1];
