code.java:
public int truckTour(int[][] pumps) {
    int n = pumps.length;
    long total = 0;
    long tank = 0;
    int start = 0;
    for (int i = 0; i < n; i++) {
        long diff = (long) pumps[i][0] - pumps[i][1];
        total += diff;
        tank += diff;
        if (tank < 0) {
            start = i + 1;
            tank = 0;
        }
    }
    return total >= 0 ? start : -1;
}

